namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, LoyaltyCapCents);

    public int TotalDiscount(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPart(subtotalCents, tier);
        var promoPart = PromoPart(subtotalCents - loyaltyPart, promoCode);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }

    private static int PromoPart(int remainingCents, string? promoCode) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min(remainingCents / 10, Summer10CapCents),
            _ => 0
        };

    private static int RatePercent(LoyaltyTier tier) =>
        tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 10,
            LoyaltyTier.Gold => 15,
            LoyaltyTier.Platinum => 20,
            _ => 0
        };
}
EOF
